/** Private session state and public account inventory share stable AWS IDs. */
import { Schema } from "effect";
import { ChoiceRequired } from "./safe-result.ts";
import { IdentitySessionSchema, PendingIdentitySessionSchema } from "./identity-client.ts";
export const Target = Schema.Struct({
  accountId: Schema.NonEmptyString,
  roleName: Schema.NonEmptyString,
});
export const InventoryAccount = Schema.Struct({
  accountId: Schema.NonEmptyString,
  accountName: Schema.NonEmptyString,
  roles: Schema.Array(Schema.NonEmptyString),
  production: Schema.Boolean,
});
export const SavedSession = Schema.Struct({
  session: IdentitySessionSchema,
  accounts: Schema.Array(InventoryAccount),
  defaultTarget: Schema.optionalKey(Target),
  reauthenticationRequired: Schema.optionalKey(Schema.Boolean),
});
export type SavedSession = typeof SavedSession.Type;
export const PendingSession = Schema.Struct({
  ref: Schema.NonEmptyString,
  baseRevision: Schema.optionalKey(Schema.Number),
  startUrl: Schema.optionalKey(Schema.String),
  region: Schema.optionalKey(Schema.String),
  pending: Schema.optionalKey(PendingIdentitySessionSchema),
  nextPollAt: Schema.Number,
});
export const guardedName = (name: string) => /(?:^|[^a-z])prod(?:uction)?(?:$|[^a-z])/iu.test(name);
export const assignedInventory = async (
  aws: ReturnType<typeof import("./identity-client.ts").makeIdentityCenter>,
  session: typeof IdentitySessionSchema.Type,
  previous: readonly (typeof InventoryAccount.Type)[] = [],
) => {
  const assigned = await aws.listAccounts(session),
    accounts: (typeof InventoryAccount.Type)[] = [];
  const seen = new Set<string>();
  for (const account of assigned) {
    if (seen.has(account.accountId))
      throw new ChoiceRequired("AWS returned a duplicate account assignment. Refresh and retry.");
    seen.add(account.accountId);
    const old = previous.find((saved) => saved.accountId === account.accountId);
    const roles = await aws.listRoles(session, account.accountId);
    accounts.push({
      accountId: account.accountId,
      accountName: account.accountName,
      roles: [...new Set(roles.map((role) => role.roleName))],
      production: old?.production ?? guardedName(account.accountName),
    });
  }
  return accounts;
};
/** Resolve the target once per call. A missing or ambiguous name never chooses another account. */
export const resolveTarget = (state: SavedSession, account?: string, role?: string) => {
  if (account === undefined && role !== undefined)
    throw new ChoiceRequired("Choose an AWS account with that role.");
  const selection = account === undefined ? state.defaultTarget : undefined;
  if (account === undefined && selection === undefined)
    throw new ChoiceRequired(
      "Choose an AWS account and role for this task, or save a default first.",
    );
  const name = account ?? selection?.accountId;
  const matches = state.accounts.filter(
    (item) =>
      item.accountId === name || item.accountName.toLocaleLowerCase() === name?.toLocaleLowerCase(),
  );
  if (matches.length !== 1)
    throw new ChoiceRequired(
      matches.length === 0
        ? "That AWS account is not assigned to you. Refresh accounts or choose another account."
        : "More than one AWS account has that name. Choose its account ID.",
    );
  const selected = matches[0];
  if (selected === undefined) throw new ChoiceRequired("Choose an assigned AWS account.");
  const chosenRole =
    role ?? selection?.roleName ?? (selected.roles.length === 1 ? selected.roles[0] : undefined);
  if (chosenRole === undefined)
    throw new ChoiceRequired("Choose an assigned role for this AWS account.");
  if (!selected.roles.includes(chosenRole))
    throw new ChoiceRequired(
      "That AWS role is no longer assigned to you. Refresh accounts or choose another role.",
    );
  return { account: selected, roleName: chosenRole };
};

import { accountRouter, defineApp, router, withApprovals } from "apps";
import { always } from "apps/operations/approval";
import { mcpRouter } from "apps/mcp";
import { icons } from "./icon.ts";
import { endpoint } from "./provider.ts";
import { requirements } from "./requirements.ts";
import { connection } from "./connection.ts";
import { createOperations } from "./operations.ts";

export default defineApp(requirements, async ({ user, cache, signal }) => ({
  tools: router(
    await accountRouter(
      [...(user?.accounts.identityCenter ?? []), ...(user?.accounts.aws ?? [])],
      async (account) =>
        account.method === "identityCenter"
          ? router(createOperations(account.id))
          : withApprovals(
              await mcpRouter({
                url: endpoint,
                account,
                headers: account.headers(),
                cache,
                signal,
              }),
              () => always(),
            ),
      { signal },
    ),
    {
      title: "AWS",
      icons,
      description:
        "Use your assigned AWS accounts and roles. Each task has its own target; production changes and opaque scripts ask for approval.",
    },
  ),
  connect: { identityCenter: connection },
}));

/** Every request resolves its own AWS account and role before acquiring temporary credentials. */
import {
  mutation,
  query,
  object,
  string,
  boolean,
  record,
  json,
  type MutationContext,
  type QueryContext,
} from "apps";
import { callMcpTool } from "apps/mcp";
import { AwsClient } from "./vendor/aws4fetch.js";
import { requirements } from "./requirements.ts";
import { managedMcpEndpoint } from "./wire.ts";
import { writePrivate } from "./session-store.ts";
import { assignedInventory, resolveTarget } from "./identity-state.ts";
import { safeResult, ChoiceRequired } from "./safe-result.ts";
import { load, fresh, sessionRequest, awsFor, publicConnection } from "./saved-connection.ts";
type Context = MutationContext<typeof requirements>;
type ReadContext = QueryContext<typeof requirements>;
export const createOperations = (connectionId: string) => {
  const inventory = query(
    {
      input: object({}),
      description:
        "Your AWS account and role assignments, saved default and production guards. Session secrets are never returned.",
    },
    async (ctx: ReadContext) =>
      safeResult(async () => {
        const connections = [];
        for (const account of ctx.user.accounts.identityCenter) {
          if (account.method !== "identityCenter") continue;
          if (account.id !== connectionId) continue;
          const saved = await load(ctx, account.id);
          connections.push(publicConnection(account.id, saved.value));
        }
        return { connections };
      }),
  );
  const refresh = mutation(
    {
      input: object({}),
      description:
        "Refresh the accounts and roles AWS assigns to this connection. Retains its default and production classifications.",
    },
    async (ctx: Context) =>
      safeResult(async () => {
        const stored = await fresh(ctx, connectionId),
          accounts = await sessionRequest(ctx, stored, () =>
            assignedInventory(
              awsFor(ctx, stored.value),
              stored.value.session,
              stored.value.accounts,
            ),
          );
        const value = { ...stored.value, accounts };
        await writePrivate(
          ctx.sql,
          "identity_sessions",
          stored.owner,
          stored.reference,
          value,
          stored.revision,
        );
        return publicConnection(stored.account.id, value);
      }),
  );
  const setDefault = mutation(
    {
      input: object({ accountId: string().optional(), roleName: string().optional() }),
      description:
        "Explicitly save an assigned AWS account and role as your default, or omit both to clear it.",
    },
    async (ctx: Context, input) =>
      safeResult(async () => {
        const stored = await load(ctx, connectionId);
        if ((input.accountId === undefined) !== (input.roleName === undefined))
          throw new ChoiceRequired("Choose both an AWS account and role, or clear both.");
        const target =
          input.accountId === undefined
            ? undefined
            : resolveTarget(stored.value, input.accountId, input.roleName);
        const { defaultTarget: _old, ...rest } = stored.value;
        const value = {
          ...rest,
          ...(target === undefined
            ? {}
            : {
                defaultTarget: { accountId: target.account.accountId, roleName: target.roleName },
              }),
        };
        await writePrivate(
          ctx.sql,
          "identity_sessions",
          stored.owner,
          stored.reference,
          value,
          stored.revision,
        );
        return publicConnection(stored.account.id, value);
      }),
  );
  const setProduction = mutation(
    {
      input: object({ accountId: string(), production: boolean() }),
      description:
        "Set a production guard by stable AWS account ID. Renaming the account never changes this choice.",
    },
    async (ctx: Context, input) =>
      safeResult(async () => {
        const stored = await load(ctx, connectionId);
        if (!stored.value.accounts.some((account) => account.accountId === input.accountId))
          throw new ChoiceRequired("Choose an assigned AWS account.");
        const value = {
          ...stored.value,
          accounts: stored.value.accounts.map((account) =>
            account.accountId === input.accountId
              ? { ...account, production: input.production }
              : account,
          ),
        };
        await writePrivate(
          ctx.sql,
          "identity_sessions",
          stored.owner,
          stored.reference,
          value,
          stored.revision,
        );
        return publicConnection(stored.account.id, value);
      }),
  );
  const callInput = object({
    account: string().optional(),
    role: string().optional(),
    arguments: record(json()),
  });
  const callTool = (name: "get_tasks" | "run_script" | "get_presigned_url") =>
    mutation(
      {
        input: callInput,
        description: `AWS ${name}. Choose an assigned account name or ID and role for this task. Only an explicitly saved default may fill an omitted target. Scripts and presigned URLs require human approval of the exact target and arguments.`,
      },
      async (ctx: Context, input) =>
        safeResult(async () => {
          const stored = await fresh(ctx, connectionId),
            aws = awsFor(ctx, stored.value);
          const accounts = await sessionRequest(ctx, stored, () =>
            assignedInventory(aws, stored.value.session, stored.value.accounts),
          );
          const state = { ...stored.value, accounts },
            target = resolveTarget(state, input.account, input.role);
          const receipt = {
            connection: stored.account.id,
            accountId: target.account.accountId,
            accountName: target.account.accountName,
            roleName: target.roleName,
            production: target.account.production,
            operation: name,
            arguments: input.arguments,
          };
          // Opaque scripts can change any service. An agent's read-only claim never bypasses consent.
          if (name !== "get_tasks") {
            const decision = await ctx.elicit({
              mode: "form",
              message: `Approve this AWS operation?\n${JSON.stringify(receipt, null, 2)}`,
              requestedSchema: { type: "object", properties: {} },
            });
            if (
              decision.action !== "accept" ||
              (decision.content !== undefined && Object.keys(decision.content).length !== 0)
            )
              return { state: "denied", target: receipt };
            const current = await load(ctx, connectionId);
            if (current.revision !== stored.revision)
              throw new ChoiceRequired(
                "Your AWS connection or settings changed while approval was pending. Review and approve a fresh request.",
              );
          }
          const credentials = await sessionRequest(ctx, stored, () =>
            aws.getRoleCredentials(stored.value.session, target.account.accountId, target.roleName),
          );
          const signer = new AwsClient({ ...credentials, service: "aws-mcp", region: "us-east-1" });
          const result = await callMcpTool(
            {
              url: managedMcpEndpoint,
              accountId: stored.account.id,
              signal: ctx.signal,
              signRequest: (request) => signer.sign(request),
            },
            name,
            input.arguments,
            { elicit: ctx.elicit },
          );
          return { target: receipt, result };
        }),
    );
  const get_tasks = callTool("get_tasks"),
    run_script = callTool("run_script"),
    get_presigned_url = callTool("get_presigned_url");

  return {
    inventory,
    refresh,
    setDefault,
    setProduction,
    get_tasks,
    run_script,
    get_presigned_url,
  };
};

