import { aws, identityCenter } from "./provider.ts";
import { icons } from "./icon.ts";
export const requirements = {
  user: { accounts: { aws: aws.many(), identityCenter: identityCenter.many() } },
  icons,
};

import { AwsIdentityError } from "./errors.ts";
export class ChoiceRequired extends Error {
  readonly name = "ChoiceRequired";
}
export const safeResult = async <A>(work: () => Promise<A>) => {
  try {
    return { ok: true as const, value: await work() };
  } catch (error) {
    if (error instanceof AwsIdentityError)
      return {
        ok: false as const,
        state: error.failure,
        message: error.message,
        retryable: error.retryable,
      };
    if (error instanceof ChoiceRequired)
      return {
        ok: false as const,
        state: "choice_required",
        message: error.message,
        retryable: false,
      };
    return {
      ok: false as const,
      state: "unavailable",
      message:
        "AWS could not complete this request. Keep your connection and retry. No different account or role was selected.",
      retryable: true,
    };
  }
};

/** Saved connection ownership, refresh and visible recovery state. */
import type { MutationContext, QueryContext } from "apps";
import { requirements } from "./requirements.ts";
import { makeIdentityCenter } from "./identity-client.ts";
import { AwsIdentityError } from "./errors.ts";
import { identityEndpoints } from "./wire.ts";
import { readPrivate, writePrivate, claimPrivate } from "./session-store.ts";
import { SavedSession } from "./identity-state.ts";
import { ChoiceRequired } from "./safe-result.ts";
type Context = MutationContext<typeof requirements>;
type ReadContext = QueryContext<typeof requirements>;
const accountFor = (ctx: ReadContext, connection?: string) => {
  const accounts = ctx.user.accounts.identityCenter.filter(
    (account) => account.method === "identityCenter",
  );
  const matches =
    connection === undefined ? accounts : accounts.filter((account) => account.id === connection);
  if (matches.length !== 1)
    throw new ChoiceRequired(
      matches.length === 0
        ? "Connect AWS Identity Center in Accounts first."
        : "Choose the saved AWS connection for this task.",
    );
  const account = matches[0];
  if (account?.method !== "identityCenter")
    throw new ChoiceRequired("Choose an AWS Identity Center connection.");
  if (!ctx.user.id) throw new ChoiceRequired("Sign in to use your AWS connection.");
  return { account, owner: ctx.user.id, reference: account.fields.ref };
};
export const load = async (ctx: ReadContext, connection?: string) => {
  const selected = accountFor(ctx, connection),
    stored = await readPrivate(
      ctx.sql,
      "identity_sessions",
      selected.owner,
      selected.reference,
      SavedSession,
    );
  if (!stored) throw new AwsIdentityError("session_expired", false);
  return { ...selected, ...stored };
};
/** Keep the connection and choices when AWS revokes a session. A newer sign-in wins the revision check. */
export const sessionRequest = async <A>(
  ctx: Context,
  stored: Awaited<ReturnType<typeof load>>,
  work: () => Promise<A>,
) => {
  try {
    return await work();
  } catch (error) {
    if (error instanceof AwsIdentityError && error.failure === "session_expired")
      await writePrivate(
        ctx.sql,
        "identity_sessions",
        stored.owner,
        stored.reference,
        { ...stored.value, reauthenticationRequired: true },
        stored.revision,
      );
    throw error;
  }
};
export const awsFor = (ctx: ReadContext, state: SavedSession) =>
  makeIdentityCenter({ ...state.session, fetch: ctx.fetch, endpoints: identityEndpoints() });
/** Refresh has one claim. A failed or concurrent refresh never replaces a newer saved session. */
export const fresh = async (ctx: Context, connection?: string) => {
  let stored = await load(ctx, connection);
  if (stored.value.reauthenticationRequired) throw new AwsIdentityError("session_expired", false);
  if (stored.value.session.accessTokenExpiresAt > Date.now() + 30_000) return stored;
  const release = claimPrivate(
    ctx.sql,
    "identity_sessions",
    stored.owner,
    stored.reference,
    stored.revision,
  );
  try {
    const session = await sessionRequest(ctx, stored, () =>
      awsFor(ctx, stored.value).refresh(stored.value.session),
    );
    await writePrivate(
      ctx.sql,
      "identity_sessions",
      stored.owner,
      stored.reference,
      { ...stored.value, session },
      stored.revision,
    );
    stored = await load(ctx, connection);
    return stored;
  } finally {
    release();
  }
};
export const publicConnection = (connection: string, state: SavedSession) => ({
  connection,
  startUrl: state.session.startUrl,
  region: state.session.region,
  expiresAt: state.session.accessTokenExpiresAt,
  accounts: state.accounts,
  defaultTarget: state.defaultTarget ?? null,
  state:
    !state.reauthenticationRequired &&
    (state.session.accessTokenExpiresAt > Date.now() ||
      (state.session.refreshToken !== undefined &&
        state.session.clientSecretExpiresAt * 1000 > Date.now() &&
        (state.session.refreshTokenExpiresAt === undefined ||
          state.session.refreshTokenExpiresAt > Date.now())))
      ? "connected"
      : "session_expired",
});

/** Session keys stay in the host-encrypted account reference, outside app SQL. */
import { Schema } from "effect";
import type { Sql, SqlReader } from "apps/contracts";

const hex = (bytes: Uint8Array) =>
  Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
const bytes = (text: string) =>
  Uint8Array.from(text.match(/../gu) ?? [], (byte) => Number.parseInt(byte, 16));
const Reference = /^sso:([0-9a-f-]{36}):([0-9a-f]{64})$/u;
const Stored = Schema.Struct({
  ciphertext: Schema.String,
  revision: Schema.Number,
  lease: Schema.NullOr(Schema.String),
  lease_until: Schema.Number,
});
export type PrivateTable = "identity_sessions" | "identity_attempts";
export const newReference = () =>
  `sso:${crypto.randomUUID()}:${hex(crypto.getRandomValues(new Uint8Array(32)))}`;
const parts = (reference: string) => {
  const match = Reference.exec(reference);
  if (!match?.[1] || !match[2])
    throw new Error(
      "The saved AWS connection reference is invalid. Re-sign in without deleting the account.",
    );
  return { id: match[1], key: bytes(match[2]) };
};
const cipherKey = (key: Uint8Array<ArrayBuffer>) =>
  crypto.subtle.importKey("raw", key, "AES-GCM", false, ["encrypt", "decrypt"]);
const seal = async (owner: string, reference: string, value: unknown) => {
  const { id, key } = parts(reference),
    nonce = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv: nonce, additionalData: new TextEncoder().encode(`${owner}:${id}`) },
    await cipherKey(key),
    new TextEncoder().encode(JSON.stringify(value)),
  );
  return `${hex(nonce)}:${hex(new Uint8Array(ciphertext))}`;
};
export const readPrivate = async <A>(
  sql: SqlReader,
  table: PrivateTable,
  owner: string,
  reference: string,
  schema: Schema.Decoder<A>,
) => {
  const { id, key } = parts(reference);
  const row = sql
    .exec(
      `SELECT ciphertext, revision, lease, lease_until FROM ${table} WHERE id = ? AND owner = ?`,
      id,
      owner,
    )
    .toArray()[0];
  if (!row) return undefined;
  const stored = Schema.decodeUnknownSync(Stored)(row),
    [nonce, ciphertext] = stored.ciphertext.split(":");
  if (!nonce || !ciphertext)
    throw new Error(
      "The saved AWS session could not be read. Re-sign in without deleting the account.",
    );
  const plaintext = await crypto.subtle.decrypt(
    {
      name: "AES-GCM",
      iv: bytes(nonce),
      additionalData: new TextEncoder().encode(`${owner}:${id}`),
    },
    await cipherKey(key),
    bytes(ciphertext),
  );
  const value = Schema.decodeUnknownSync(Schema.fromJsonString(schema))(
    new TextDecoder().decode(plaintext),
  );
  return {
    value,
    revision: stored.revision,
    busy: stored.lease !== null && stored.lease_until > Date.now(),
  };
};
/** Replace only the revision the caller actually read; never overwrite another refresh or sign-in. */
export const writePrivate = async (
  sql: Sql,
  table: PrivateTable,
  owner: string,
  reference: string,
  value: unknown,
  revision?: number,
) => {
  const { id } = parts(reference),
    ciphertext = await seal(owner, reference, value);
  if (revision === undefined) {
    sql.exec(`INSERT INTO ${table} (id,owner,ciphertext) VALUES (?,?,?)`, id, owner, ciphertext);
    return;
  }
  const saved = sql.exec(
    `UPDATE ${table} SET ciphertext = ?, revision = revision + 1, lease = NULL, lease_until = 0 WHERE id = ? AND owner = ? AND revision = ?`,
    ciphertext,
    id,
    owner,
    revision,
  );
  if (saved.rowsWritten !== 1)
    throw new Error("AWS sign-in changed while this request was running. Retry the request.");
};
export const removePrivate = (sql: Sql, table: PrivateTable, owner: string, reference: string) => {
  sql.exec(`DELETE FROM ${table} WHERE id = ? AND owner = ?`, parts(reference).id, owner);
};
/** A refresh claim ends before the host's invocation deadline; no SQL transaction spans HTTP. */
export const claimPrivate = (
  sql: Sql,
  table: PrivateTable,
  owner: string,
  reference: string,
  revision: number,
) => {
  const lease = crypto.randomUUID(),
    now = Date.now();
  const claimed = sql.exec(
    `UPDATE ${table} SET lease = ?, lease_until = ? WHERE id = ? AND owner = ? AND revision = ? AND (lease IS NULL OR lease_until < ?)`,
    lease,
    now + 15_000,
    parts(reference).id,
    owner,
    revision,
    now,
  );
  if (claimed.rowsWritten !== 1)
    throw new Error("AWS session refresh is already running. Retry the request shortly.");
  return () => {
    sql.exec(
      `UPDATE ${table} SET lease = NULL, lease_until = 0 WHERE id = ? AND owner = ? AND lease = ?`,
      parts(reference).id,
      owner,
      lease,
    );
  };
};

import { useId, useState } from "react";
import type { Busy, ConnectionState } from "./connection-state.ts";
import type { AwsConnection, Receipt, Target } from "./model.ts";

function ReceiptView({ receipt }: { receipt: Receipt }) {
  return (
    <div className="receipt">
      <strong className={receipt.failed ? "refused" : "check"}>
        {receipt.failed ? "AWS refused the request" : "Access works"}
      </strong>
      <dl>
        <dt>Account</dt>
        <dd>
          {receipt.accountName}
          <br />
          <small>{receipt.accountId}</small>
        </dd>
        <dt>Role</dt>
        <dd>{receipt.roleName}</dd>
        <dt>Production</dt>
        <dd>{receipt.production ? "Yes" : "No"}</dd>
        <dt>Operation</dt>
        <dd>
          <code>{receipt.operation}</code>
        </dd>
        <dt>Arguments</dt>
        <dd>
          <code>{receipt.arguments}</code>
        </dd>
        <dt>Connection</dt>
        <dd>
          <code>{receipt.connection}</code>
        </dd>
      </dl>
      {receipt.text.length === 0 ? (
        <p className="note">AWS returned no text.</p>
      ) : (
        <details className="help">
          <summary>AWS response</summary>
          <pre>{receipt.text.join("\n\n")}</pre>
        </details>
      )}
    </div>
  );
}

/**
 * Sends one real get_tasks read with the chosen account and role and shows what AWS ran it as.
 * Nothing here selects a target for later tasks; that's what the default is for.
 */
export function AccessCheck({
  connection,
  busy,
  result,
  onCheck,
}: {
  connection: AwsConnection;
  busy: Busy | undefined;
  result: ConnectionState["check"];
  onCheck: (target: Target) => void;
}) {
  const id = useId();
  const [accountId, setAccountId] = useState("");
  const [roleChoice, setRoleChoice] = useState("");
  const account = connection.accounts.find((item) => item.accountId === accountId);
  const role =
    account === undefined
      ? ""
      : account.roles.includes(roleChoice)
        ? roleChoice
        : account.roles.length === 1
          ? (account.roles[0] ?? "")
          : "";
  const checking = busy?.kind === "check";
  return (
    <section className="access" aria-labelledby={`${id}-heading`}>
      <h3 id={`${id}-heading`}>Check access</h3>
      <p className="muted">
        Sends one read-only AWS request with exactly this account and role and shows what AWS ran it
        as. Your default stays unchanged.
      </p>
      <form
        className="fields"
        onSubmit={(event) => {
          event.preventDefault();
          if (account !== undefined && role !== "")
            onCheck({ accountId: account.accountId, roleName: role });
        }}
      >
        <div className="field">
          <label htmlFor={`${id}-account`}>Account</label>
          <select
            id={`${id}-account`}
            value={accountId}
            required
            onChange={(event) => setAccountId(event.target.value)}
          >
            <option value="">Choose an account</option>
            {connection.accounts.map((item) => (
              <option key={item.accountId} value={item.accountId}>
                {item.accountName} · {item.accountId}
              </option>
            ))}
          </select>
        </div>
        <div className="field">
          <label htmlFor={`${id}-role`}>Role</label>
          <select
            id={`${id}-role`}
            value={role}
            required
            disabled={account === undefined}
            onChange={(event) => setRoleChoice(event.target.value)}
          >
            <option value="">
              {account === undefined ? "Choose an account first" : "Choose a role"}
            </option>
            {account?.roles.map((name) => (
              <option key={name} value={name}>
                {name}
              </option>
            ))}
          </select>
        </div>
        <button
          type="submit"
          className="primary"
          disabled={busy !== undefined || account === undefined || role === ""}
        >
          {checking ? "Checking…" : "Check selected access"}
        </button>
      </form>
      <div aria-live="polite">
        {result !== undefined &&
          (result.outcome.ok ? (
            <ReceiptView receipt={result.outcome.value} />
          ) : (
            <div className="notice warn">
              <strong className="noticetitle">Check failed</strong>
              <p>{result.outcome.problem.message}</p>
              <p className="note">
                Requested {result.target.accountId} · {result.target.roleName}. No other account or
                role was tried.
              </p>
            </div>
          ))}
      </div>
    </section>
  );
}

/**
 * Calls to this app's own AWS operations through apps/client. Every request uses the native
 * accountRouter envelope {accountId, input}, and every response is schema-validated before use.
 */
import {
  array,
  boolean,
  json,
  number,
  object,
  string,
  type Infer,
  type JsonObject,
  type Schema,
} from "apps";
import { createAppClient, type OperationReference } from "apps/client";
import {
  connectionFrom,
  receiptFrom,
  type AwsConnection,
  type Outcome,
  type Problem,
  type Receipt,
  type Target,
} from "./model.ts";

const client = createAppClient();

const Account = object({
  accountId: string(),
  accountName: string(),
  roles: array(string()),
  production: boolean(),
});
const Connection = object({
  connection: string(),
  startUrl: string(),
  region: string(),
  expiresAt: number(),
  accounts: array(Account),
  // An object or null; model.ts narrows it.
  defaultTarget: json(),
  state: string(),
});
const Check = object({
  target: object({
    connection: string(),
    accountId: string(),
    accountName: string(),
    roleName: string(),
    production: boolean(),
    operation: string(),
    arguments: json(),
  }),
  result: object({ content: array(json()).optional(), isError: boolean().optional() }),
});

/** Every operation answers {ok:true,value} or {ok:false,state,message,retryable}. */
const result = <T>(value: Schema<T, boolean>) =>
  object({
    ok: boolean(),
    value: value.optional(),
    state: string().optional(),
    message: string().optional(),
    retryable: boolean().optional(),
  });
const InventoryResult = result(object({ connections: array(Connection) }));
const ConnectionResult = result(Connection);
const CheckResult = result(Check);

type Routed<Input> = { readonly accountId: string; readonly input: Input };
type NoInput = { readonly [key: string]: never };
const reference = <Input, Output, Kind extends "query" | "mutation">(
  name: string,
  kind: Kind,
): OperationReference<Routed<Input>, Output, Kind> => ({ name, kind });

const inventory = reference<NoInput, Infer<typeof InventoryResult>, "query">("inventory", "query");
const refresh = reference<NoInput, Infer<typeof ConnectionResult>, "mutation">(
  "refresh",
  "mutation",
);
const setDefault = reference<
  { readonly accountId?: string; readonly roleName?: string },
  Infer<typeof ConnectionResult>,
  "mutation"
>("setDefault", "mutation");
const setProduction = reference<
  { readonly accountId: string; readonly production: boolean },
  Infer<typeof ConnectionResult>,
  "mutation"
>("setProduction", "mutation");
const getTasks = reference<
  { readonly account: string; readonly role: string; readonly arguments: JsonObject },
  Infer<typeof CheckResult>,
  "mutation"
>("get_tasks", "mutation");

const invalid: Problem = {
  state: "invalid_response",
  message:
    "AWS returned a response this page couldn't use. Your connection is unchanged. Try again.",
  retryable: true,
};
const unreachable: Problem = {
  state: "transport",
  message:
    "This page couldn't reach your AWS connection. Your saved choices are unchanged. Try again.",
  retryable: true,
};
/** Legacy OAuth connections have no inventory; their read fails before reaching the app. */
const unlisted: Problem = {
  state: "transport",
  message:
    "This connection couldn't be loaded. If it uses the older AWS sign-in, connect AWS Identity Center in Accounts. Your older AWS sign-in stays available. Otherwise, try again.",
  retryable: true,
};

type Wire<T> = {
  readonly ok: boolean;
  readonly value?: T | undefined;
  readonly state?: string | undefined;
  readonly message?: string | undefined;
  readonly retryable?: boolean | undefined;
};
/** ok:true without a usable value is not success. */
const settle = <T, A>(wire: Wire<T>, read: (value: T) => A | undefined): Outcome<A> => {
  if (!wire.ok)
    return {
      ok: false,
      problem: {
        state: wire.state ?? "unavailable",
        message: wire.message ?? unreachable.message,
        retryable: wire.retryable ?? true,
      },
    };
  const value = wire.value === undefined ? undefined : read(wire.value);
  return value === undefined ? { ok: false, problem: invalid } : { ok: true, value };
};
const failed =
  <A>(problem: Problem) =>
  (): Outcome<A> => ({ ok: false, problem });

export const aws = {
  inventory: (id: string): Promise<Outcome<AwsConnection>> =>
    client
      .query(inventory, { accountId: id, input: {} }, InventoryResult)
      .then((wire): Outcome<AwsConnection> =>
        wire.ok && wire.value?.connections.length === 0
          ? { ok: false, problem: unlisted }
          : settle(wire, (value) => {
              const found = value.connections.find((item) => item.connection === id);
              return found === undefined ? undefined : connectionFrom(found);
            }),
      )
      .catch(failed<AwsConnection>(unlisted)),
  /** Revalidates accounts and roles with AWS; keeps the default and production marks. */
  refresh: (id: string): Promise<Outcome<AwsConnection>> =>
    client
      .mutate(refresh, { accountId: id, input: {} }, ConnectionResult)
      .then((wire) => settle(wire, connectionFrom))
      .catch(failed<AwsConnection>(unreachable)),
  /** Null clears the default; a target sets both fields. */
  setDefault: (id: string, target: Target | null): Promise<Outcome<AwsConnection>> =>
    client
      .mutate(
        setDefault,
        {
          accountId: id,
          input: target === null ? {} : { accountId: target.accountId, roleName: target.roleName },
        },
        ConnectionResult,
      )
      .then((wire) => settle(wire, connectionFrom))
      .catch(failed<AwsConnection>(unreachable)),
  setProduction: (
    id: string,
    accountId: string,
    production: boolean,
  ): Promise<Outcome<AwsConnection>> =>
    client
      .mutate(setProduction, { accountId: id, input: { accountId, production } }, ConnectionResult)
      .then((wire) => settle(wire, connectionFrom))
      .catch(failed<AwsConnection>(unreachable)),
  /** One real get_tasks read with an explicit account and role, never the saved default. */
  checkAccess: (id: string, target: Target): Promise<Outcome<Receipt>> =>
    client
      .mutate(
        getTasks,
        {
          accountId: id,
          input: { account: target.accountId, role: target.roleName, arguments: {} },
        },
        CheckResult,
      )
      .then((wire) => settle(wire, receiptFrom))
      .catch(failed<Receipt>(unreachable)),
  /** Fires when the host shows or hides this page, such as returning from the Accounts tab. */
  onActiveChange: client.onActiveChange,
};

export type AwsApi = typeof aws;

import type { AwsApi } from "./api.ts";
import { ConnectionSection } from "./connection.tsx";
import { AccountsLink, Notice } from "./controls.tsx";

export function App({
