/**
 * One saved connection's inventory and its writes. Writes run one at a time per connection, and a
 * failure keeps the last good inventory and choices on screen.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import type { AwsApi } from "./api.ts";
import {
  targetLabel,
  type AwsAccount,
  type AwsConnection,
  type Outcome,
  type Problem,
  type Receipt,
  type Target,
} from "./model.ts";

export type Busy =
  | { readonly kind: "refresh" }
  | { readonly kind: "default"; readonly target: Target | null }
  | { readonly kind: "production"; readonly accountId: string; readonly production: boolean }
  | { readonly kind: "check"; readonly target: Target };

/** Where a problem came from decides what "Try again" repeats. */
export interface SourcedProblem {
  readonly source: "load" | "refresh" | "write";
  readonly problem: Problem;
}

export interface ConnectionState {
  readonly loading: boolean;
  readonly value?: AwsConnection | undefined;
  readonly problem?: SourcedProblem | undefined;
  readonly busy?: Busy | undefined;
  readonly notice?: string | undefined;
  readonly check?: { readonly target: Target; readonly outcome: Outcome<Receipt> } | undefined;
}

export function useConnection(api: AwsApi, id: string) {
  const [state, setState] = useState<ConnectionState>({ loading: true });
  const reads = useRef(0);
  const writing = useRef(false);

  const load = useCallback(() => {
    const read = ++reads.current;
    setState((current) => ({ ...current, loading: true }));
    void api.inventory(id).then((outcome) => {
      // A newer read or any write answered after this read started.
      if (read !== reads.current) return;
      setState((current) =>
        outcome.ok
          ? { ...current, loading: false, value: outcome.value, problem: undefined }
          : { ...current, loading: false, problem: { source: "load", problem: outcome.problem } },
      );
    });
  }, [api, id]);

  // Coming back from the Accounts tab, such as after re-sign-in, reads the inventory again.
  useEffect(() => {
    load();
    return api.onActiveChange((active) => {
      if (active && !writing.current) load();
    });
  }, [api, load]);

  const write = (
    busy: Busy,
    run: () => Promise<Outcome<AwsConnection>>,
    done: (value: AwsConnection) => string,
  ) => {
    if (writing.current) return;
    writing.current = true;
    reads.current++;
    setState((current) => ({ ...current, busy, notice: undefined }));
    void run().then((outcome) => {
      writing.current = false;
      setState((current) =>
        outcome.ok
          ? {
              ...current,
              loading: false,
              busy: undefined,
              value: outcome.value,
              problem: undefined,
              notice: done(outcome.value),
            }
          : {
              ...current,
              loading: false,
              busy: undefined,
              problem: {
                source: busy.kind === "refresh" ? "refresh" : "write",
                problem: outcome.problem,
              },
            },
      );
    });
  };

  return {
    state,
    load,
    refresh: () =>
      write(
        { kind: "refresh" },
        () => api.refresh(id),
        (value) =>
          value.accounts.length === 0
            ? "Refreshed. AWS returned no assigned accounts."
            : "Account list refreshed from AWS.",
      ),
    setDefault: (target: Target | null) =>
      write(
        { kind: "default", target },
        () => api.setDefault(id, target),
        (value) =>
          value.defaultTarget === null
            ? "Default cleared. Tasks now name their account and role."
            : `Default saved: ${targetLabel(value, value.defaultTarget)}.`,
      ),
    setProduction: (account: AwsAccount, production: boolean) =>
      write(
        { kind: "production", accountId: account.accountId, production },
        () => api.setProduction(id, account.accountId, production),
        () =>
          production
            ? `${account.accountName} is marked as production.`
            : `${account.accountName} is no longer marked as production.`,
      ),
    check: (target: Target) => {
      if (writing.current) return;
      writing.current = true;
      setState((current) => ({ ...current, busy: { kind: "check", target }, check: undefined }));
      void api.checkAccess(id, target).then((outcome) => {
        writing.current = false;
        setState((current) => ({ ...current, busy: undefined, check: { target, outcome } }));
      });
    },
  };
}

export type ConnectionControls = ReturnType<typeof useConnection>;

import { useId } from "react";
import type { AwsApi } from "./api.ts";
import { AccessCheck } from "./access-check.tsx";
import { useConnection, type ConnectionState } from "./connection-state.ts";
import { AccountsLink, Notice, ProblemNotice } from "./controls.tsx";
import { Inventory } from "./inventory.tsx";
import { accountCount, portalName } from "./model.ts";

function Status({ state }: { state: ConnectionState }) {
  if (state.value === undefined) return null;
  if (state.value.expired) return <div className="status expired">Sign-in expired</div>;
  return <div className="status">{state.loading ? "Connected · updating…" : "Connected"}</div>;
}

/** One saved Identity Center connection: its real account and role inventory and the choices on it. */
export function ConnectionSection({
  api,
  id,
  accountsUrl,
}: {
  api: AwsApi;
  id: string;
  accountsUrl: string | undefined;
}) {
  const connection = useConnection(api, id);
  const { state } = connection;
  const { value, problem, busy } = state;
  const headingId = useId();
  const retry =
    problem?.source === "load"
      ? connection.load
      : problem?.source === "refresh"
        ? connection.refresh
        : undefined;
  return (
    <section className="connection" aria-labelledby={headingId}>
      <div className="connectionhead">
        <div className="min0">
          <h2 id={headingId}>
            {value === undefined ? "AWS connection" : portalName(value.startUrl)}
          </h2>
          <small>
            IAM Identity Center
            {value !== undefined && ` · ${value.region} · ${accountCount(value.accounts.length)}`}
          </small>
          {value !== undefined && <small className="url">{value.startUrl}</small>}
          <Status state={state} />
        </div>
        <div className="headactions">
          {value !== undefined && (
            <button
              type="button"
              className="quiet"
              onClick={connection.refresh}
              disabled={busy !== undefined}
            >
              {busy?.kind === "refresh" ? "Refreshing…" : "Refresh accounts"}
            </button>
          )}
          <AccountsLink href={accountsUrl}>Manage connection</AccountsLink>
        </div>
      </div>

      {problem !== undefined && (
        <ProblemNotice
          problem={problem.problem}
          retained={value !== undefined}
          onRetry={busy === undefined ? retry : undefined}
          accountsUrl={accountsUrl}
        />
      )}
      {problem === undefined && value?.expired === true && (
        <Notice
          tone="warn"
          title="Sign in to AWS again"
          actions={
            accountsUrl === undefined ? undefined : (
              <AccountsLink href={accountsUrl}>Sign in again</AccountsLink>
            )
          }
        >
          Your AWS sign-in has expired. Your accounts, default and production choices are saved.
          Refresh accounts to renew it, or sign in again from Accounts.
        </Notice>
      )}

      {value === undefined ? (
        state.loading &&
        problem === undefined && <p className="muted loading">Loading your AWS accounts…</p>
      ) : value.accounts.length === 0 ? (
        <Notice tone="warn" title="No AWS accounts available">
          Sign-in worked, but AWS returned no assigned accounts. Check that you signed in with your
          work identity, then refresh accounts.
        </Notice>
      ) : (
        <>
          <Inventory
            connection={value}
            busy={busy}
            onSetDefault={connection.setDefault}
            onSetProduction={connection.setProduction}
          />
          <AccessCheck
            connection={value}
            busy={busy}
            result={state.check}
            onCheck={connection.check}
          />
        </>
      )}

      <div role="status" aria-live="polite" className="live">
        {state.notice !== undefined && <p className="notice good">{state.notice}</p>}
      </div>
    </section>
  );
}

import type { ReactNode } from "react";
import type { Problem } from "./model.ts";

/** Opens the host's Accounts page, which owns sign-in, re-sign-in and disconnecting. */
export function AccountsLink({
  href,
  children,
  primary = false,
}: {
  href: string | undefined;
  children: ReactNode;
  primary?: boolean;
}) {
  if (href === undefined) return null;
  return (
    <a
      className={primary ? "button primary" : "button quiet"}
      href={href}
      target="_blank"
      rel="noopener"
    >
      {children}
      <span aria-hidden="true"> ↗</span>
    </a>
  );
}

export function Notice({
  tone,
  title,
  children,
  actions,
}: {
  tone: "warn" | "good";
  title?: string;
  children: ReactNode;
  actions?: ReactNode;
}) {
  return (
    <div className={`notice ${tone}`}>
      {title !== undefined && <strong className="noticetitle">{title}</strong>}
      <p>{children}</p>
      {actions !== undefined && <div className="noticeactions">{actions}</div>}
    </div>
  );
}

const titles: Readonly<Record<string, string>> = {
  session_expired: "Sign in to AWS again",
  access_denied: "AWS refused this account or role",
  no_access: "No AWS accounts available",
  rate_limited: "AWS is busy",
  unavailable: "AWS is unavailable",
  request_failed: "AWS couldn't finish",
  invalid_response: "Unexpected response",
  choice_required: "Choose again",
  transport: "Couldn't load this connection",
};
/** States the host's Accounts page resolves: re-sign-in, reconnecting or checking the identity. */
const managed = new Set(["session_expired", "no_access", "access_denied", "transport"]);

/**
 * A recoverable failure. `retained` says the last good inventory is still shown below it.
 * `onRetry` repeats the failed read or refresh; a failed write is repeated by the person.
 */
export function ProblemNotice({
  problem,
  retained,
  onRetry,
  accountsUrl,
}: {
  problem: Problem;
  retained: boolean;
  onRetry?: (() => void) | undefined;
  accountsUrl: string | undefined;
}) {
  const action =
    problem.state === "session_expired"
      ? "Sign in again"
      : managed.has(problem.state)
        ? "Manage connection"
        : undefined;
  return (
    <Notice
      tone="warn"
      title={titles[problem.state] ?? "Something went wrong"}
      actions={
        (onRetry !== undefined && problem.retryable) ||
        (action !== undefined && accountsUrl !== undefined) ? (
          <>
            {onRetry !== undefined && problem.retryable && (
              <button type="button" onClick={onRetry}>
                Try again
              </button>
            )}
            {action !== undefined && <AccountsLink href={accountsUrl}>{action}</AccountsLink>}
          </>
        ) : undefined
      }
    >
      {problem.message}
      {retained && " Your saved accounts and choices are shown below."}
    </Notice>
  );
}

/** Non-secret page context the host injects. Neither value grants any authority. */
import { array, object, record, string } from "apps";

const Context = object({ accounts: record(array(string())).optional() });

/**
 * The saved AWS connection IDs this page runs with, or undefined when the host context can't be
 * read. Legacy OAuth IDs may be among them; their inventory read fails and the page says so.
 */
export const savedConnections = (): readonly string[] | undefined => {
  const text = document.getElementById("executor-context")?.textContent;
  if (text === undefined || text === null || text === "") return undefined;
  try {
    return [...new Set(Context.parse(JSON.parse(text)).accounts?.identityCenter ?? [])];
  } catch {
    return undefined;
  }
};

/** The host's native Accounts page, which owns sign-in, re-sign-in, renaming and disconnecting. */
export const accountsUrl = (): string | undefined => {
  const content = document
    .querySelector('meta[name="executor-accounts-url"]')
    ?.getAttribute("content");
  if (content === undefined || content === null || content === "") return undefined;
  try {
    const url = new URL(content);
    return url.protocol === "https:" || url.protocol === "http:" ? url.href : undefined;
  } catch {
    return undefined;
  }
};

import { useId, useState } from "react";
import type { Busy } from "./connection-state.ts";
import { targetLabel, type AwsAccount, type AwsConnection, type Target } from "./model.ts";

function AccountRow({
  account,
  defaultTarget,
  busy,
  onSetDefault,
}: {
  account: AwsAccount;
  defaultTarget: Target | null;
  busy: Busy | undefined;
  onSetDefault: (target: Target) => void;
}) {
  const saved = defaultTarget?.accountId === account.accountId ? defaultTarget.roleName : undefined;
  const fallback =
    saved !== undefined && account.roles.includes(saved) ? saved : (account.roles[0] ?? "");
  const [choice, setChoice] = useState(fallback);
  // A refresh can remove the chosen role; fall back instead of offering a role AWS no longer assigns.
  const role = account.roles.includes(choice) ? choice : fallback;
  const saving = busy?.kind === "default" && busy.target?.accountId === account.accountId;
  return (
    <li className="account">
      <div className="min0">
        <strong>{account.accountName}</strong>{" "}
        {account.production && <span className="badge">Production</span>}
        <small className="id">{account.accountId}</small>
      </div>
      {account.roles.length > 1 ? (
        <select
          aria-label={`Role for ${account.accountName}`}
          value={role}
          onChange={(event) => setChoice(event.target.value)}
        >
          {account.roles.map((name) => (
            <option key={name} value={name}>
              {name}
            </option>
          ))}
        </select>
      ) : (
        <span className="role">{account.roles[0] ?? "No assigned role"}</span>
      )}
      {saved !== undefined && saved === role ? (
        <span className="defaultmark">Default</span>
      ) : (
        <button
          type="button"
          className="quiet"
          aria-label={`Set default: ${account.accountName} · ${role}`}
          disabled={busy !== undefined || role === ""}
          onClick={() => onSetDefault({ accountId: account.accountId, roleName: role })}
        >
          {saving ? "Saving…" : "Set default"}
        </button>
      )}
    </li>
  );
}

/** The label is exactly "Treat <name> as production"; the stable ID describes it. */
function ProductionMark({
  account,
  busy,
  onChange,
}: {
  account: AwsAccount;
  busy: Busy | undefined;
  onChange: (account: AwsAccount, production: boolean) => void;
}) {
  const id = useId();
  const pending =
    busy?.kind === "production" && busy.accountId === account.accountId ? busy : undefined;
  return (
    <div className="production">
      <input
        id={`${id}-mark`}
        type="checkbox"
        aria-describedby={`${id}-id`}
        checked={pending === undefined ? account.production : pending.production}
        disabled={busy !== undefined}
        onChange={(event) => onChange(account, event.target.checked)}
      />
      <div className="min0">
        <label htmlFor={`${id}-mark`}>Treat {account.accountName} as production</label>
        <small id={`${id}-id`}>
          {account.accountId}
          {pending !== undefined && " · Saving…"}
        </small>
      </div>
    </div>
  );
}

/** The real account and role inventory, the optional default and the production marks. */
export function Inventory({
  connection,
  busy,
  onSetDefault,
  onSetProduction,
}: {
  connection: AwsConnection;
  busy: Busy | undefined;
  onSetDefault: (target: Target | null) => void;
  onSetProduction: (account: AwsAccount, production: boolean) => void;
}) {
  const target = connection.defaultTarget;
  const clearing = busy?.kind === "default" && busy.target === null;
  return (
    <>
      <ul className="accounts" aria-label="AWS accounts">
        {connection.accounts.map((account) => (
          <AccountRow
            key={account.accountId}
            account={account}
            defaultTarget={target}
            busy={busy}
            onSetDefault={onSetDefault}
          />
        ))}
      </ul>
      <div className="row note">
        <span>
          {target === null
            ? "No default. Each task names its account and role."
            : `Default: ${targetLabel(connection, target)}`}
        </span>
        {target !== null && (
          <button
            type="button"
            className="linkbutton"
            disabled={busy !== undefined}
            onClick={() => onSetDefault(null)}
          >
            {clearing ? "Clearing…" : "Clear default"}
          </button>
        )}
      </div>
      <details className="help">
        <summary>Production protection</summary>
        <p>
          Approval requests show whether an account is production. Scripts and presigned URLs always
          ask for your approval of the exact account, role and arguments before they run, on any
          account.
        </p>
        <p>
          Saved by AWS account ID, so renaming an account in AWS keeps this choice. New accounts
          whose name includes the word “prod” or “production” start marked.
        </p>
        {connection.accounts.map((account) => (
          <ProductionMark
            key={account.accountId}
            account={account}
            busy={busy}
            onChange={onSetProduction}
          />
        ))}
      </details>
    </>
  );
}

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { aws } from "./api.ts";
import { App } from "./app.tsx";
import { accountsUrl, savedConnections } from "./host.ts";
import "./style.css";

const root = document.getElementById("root");
if (root === null) throw new Error("Missing app root");
createRoot(root).render(
  <StrictMode>
    <App api={aws} connections={savedConnections()} accountsUrl={accountsUrl()} />
  </StrictMode>,
);

/** What the page shows, built only from validated responses. Stable AWS IDs identify everything. */

export interface AwsAccount {
  readonly accountId: string;
  readonly accountName: string;
  readonly roles: readonly string[];
  readonly production: boolean;
}
export interface Target {
  readonly accountId: string;
  readonly roleName: string;
}
export interface AwsConnection {
  /** The native saved connection ID every call routes by. */
  readonly id: string;
  readonly startUrl: string;
  readonly region: string;
  readonly expiresAt: number;
  readonly accounts: readonly AwsAccount[];
  readonly defaultTarget: Target | null;
  readonly expired: boolean;
}
/** A failure the app or transport reported. Messages are already safe to show. */
export interface Problem {
  readonly state: string;
  readonly message: string;
  readonly retryable: boolean;
}
export type Outcome<A> =
  | { readonly ok: true; readonly value: A }
  | { readonly ok: false; readonly problem: Problem };
/** The exact target and arguments AWS ran a check with, as the app reported them. */
export interface Receipt {
  readonly connection: string;
  readonly accountId: string;
  readonly accountName: string;
  readonly roleName: string;
  readonly production: boolean;
  readonly operation: string;
  readonly arguments: string;
  readonly failed: boolean;
  readonly text: readonly string[];
}

const targetFrom = (value: unknown): Target | null | undefined => {
  if (value === null) return null;
  if (typeof value !== "object" || value === null) return undefined;
  if (!("accountId" in value) || !("roleName" in value)) return undefined;
  const { accountId, roleName } = value;
  return typeof accountId === "string" && typeof roleName === "string"
    ? { accountId, roleName }
    : undefined;
};

/** Undefined when the response doesn't describe a connection this page understands. */
export const connectionFrom = (wire: {
  readonly connection: string;
  readonly startUrl: string;
  readonly region: string;
  readonly expiresAt: number;
  readonly accounts: readonly AwsAccount[];
  readonly defaultTarget: unknown;
  readonly state: string;
}): AwsConnection | undefined => {
  const defaultTarget = targetFrom(wire.defaultTarget);
  if (defaultTarget === undefined) return undefined;
  if (wire.state !== "connected" && wire.state !== "session_expired") return undefined;
  return {
    id: wire.connection,
    startUrl: wire.startUrl,
    region: wire.region,
    expiresAt: wire.expiresAt,
    accounts: wire.accounts,
    defaultTarget,
    expired: wire.state === "session_expired",
  };
};

const textOf = (item: unknown): string[] =>
  typeof item === "object" &&
  item !== null &&
  "type" in item &&
  item.type === "text" &&
  "text" in item &&
  typeof item.text === "string"
    ? [item.text]
    : [];

export const receiptFrom = (wire: {
  readonly target: {
    readonly connection: string;
    readonly accountId: string;
    readonly accountName: string;
    readonly roleName: string;
    readonly production: boolean;
    readonly operation: string;
    readonly arguments: unknown;
  };
  readonly result: {
    readonly content?: readonly unknown[] | undefined;
    readonly isError?: boolean | undefined;
  };
}): Receipt => ({
  connection: wire.target.connection,
  accountId: wire.target.accountId,
  accountName: wire.target.accountName,
  roleName: wire.target.roleName,
  production: wire.target.production,
  operation: wire.target.operation,
  arguments: JSON.stringify(wire.target.arguments),
  failed: wire.result.isError === true,
  text: (wire.result.content ?? []).flatMap(textOf),
});

/** The portal's own subdomain, such as "your-company" for your-company.awsapps.com/start. */
export const portalName = (startUrl: string) => {
  try {
    return new URL(startUrl).hostname.split(".")[0] || startUrl;
  } catch {
    return startUrl;
  }
};

export const accountCount = (count: number) => `${count} ${count === 1 ? "account" : "accounts"}`;

/** "Name · Role" for a saved target, or its IDs when AWS no longer assigns that account. */
export const targetLabel = (connection: AwsConnection, target: Target) => {
  const account = connection.accounts.find((item) => item.accountId === target.accountId);
  if (account === undefined) return `${target.accountId} · ${target.roleName} (no longer assigned)`;
  return account.roles.includes(target.roleName)
    ? `${account.accountName} · ${target.roleName}`
    : `${account.accountName} · ${target.roleName} (role no longer assigned)`;
};

