        headers?: HeadersInit;
        body?: BodyInit | null;
        accessKeyId: string;
        secretAccessKey: string;
        sessionToken?: string;
        service?: string;
        region?: string;
        cache?: Map<string, ArrayBuffer>;
        datetime?: string;
        signQuery?: boolean;
        appendSessionToken?: boolean;
        allHeaders?: boolean;
        singleEncode?: boolean;
    });
    method: string;
    url: URL;
    headers: Headers;
    body: BodyInit | null | undefined;
    accessKeyId: string;
    secretAccessKey: string;
    sessionToken: string | undefined;
    service: string;
    region: string;
    cache: Map<string, ArrayBuffer>;
    datetime: string;
    signQuery: boolean | undefined;
    appendSessionToken: boolean;
    signableHeaders: string[];
    signedHeaders: string;
    canonicalHeaders: string;
    credentialString: string;
    encodedPath: string;
    encodedSearch: string;
    sign(): Promise<{
        method: string;
        url: URL;
        headers: Headers;
        body?: BodyInit | null;
    }>;
    authHeader(): Promise<string>;
